  'devassist.cycle': doc('Coordinate a design/development request through the persistent DevAssist workflow.', 'Use when a development request needs structured phases and focused TDD evidence.',
    { status: 'DevAssist workflow outcome; blocked is a business outcome and may still exit 0.', devAssistSessionId: 'Continuation identity.', 'reason / nextCall': 'Why work stopped and suggested continuation input when present.', 'candidateTestPath / devAssistTracePath / timelinePath / artifacts': 'Generated candidate and evidence references when present.' },
    ['Requires a started TDD runtime. action is start/continue/regenerate; continue and regenerate require devAssistSessionId.', 'The development-assist session id differs from the connection --session id. Preserve the returned workflow state.', 'files and baseRevision describe change context; do not assume this command independently implements arbitrary source edits.'],
    [example('Start a bounded development request', { action: 'start', request: 'Verify the counter increments when Increment is tapped', files: ['lib/counter.dart'] }, session)], ['tdd.start', 'tdd.prepare', 'tdd.cycle']),
  'session.open': doc('Create a reusable local worker connected to an attached or managed Flutter app.', 'Use for repeated exploration, retained diagnostics and persistent TDD.',
    { sessionId: 'Pass this value as --session on later commands.', 'connected / endpoint': 'Connection state and resolved endpoint.', 'tdd / workflow': 'Current runtime and generation context when present.', 'pid / generation / operations': 'Worker identity and active operation ids.' },
    ['vmUrl and deviceId are mutually exclusive. Attach uses explicit/configured/discovered VM endpoint.', 'deviceId starts a managed TDD runtime automatically; do not call tdd start again. Attach mode only opens a connection until tdd start.', 'Startup budgets are 30 seconds for attach and 180 seconds for managed launch; --deadline may shorten them. Idle workers close after 30 minutes without active work.', 'Sessions are project-scoped; keep the same --cwd. A connection session is not a test run or artifact runId.'],
    [example('Open an attach session', app), example('Open a managed app and TDD runtime', { deviceId: 'DEVICE_ID', target: 'lib/main_fliwright.dart', scenario: 'logged-in' })], ['session.list', 'session.status', 'tdd.start', 'session.close']),
  'session.list': doc('Probe sessions registered under the current project.', 'Use to discover live workers and identify unreachable registrations.',
    { sessions: 'Entries with sessionId and live status, or connected:false/status:unreachable.' },
    ['Each registration is probed with a short timeout. Unreachable entries are not silently restarted or replayed.'],
    [example('List local project sessions')], ['session.status', 'session.open', 'session.close']),
  'session.status': doc('Read worker state or the journal entry of one operation.', 'Use for live monitoring and recovery after a lost command response.',
    { worker: 'Without operationId: sessionId/pid/generation/connected/endpoint/tdd/workflow/operations.', operation: 'With operationId: queued/running/succeeded/failed/cancelled journal state and available data/error.' },
    ['Requires --session or FLIWRIGHT_SESSION. operationId is the envelope operationId from a routed command.', 'Status can be queried during long work. Do not retry uncertain mutations until their recorded outcome is understood. Missing journal data does not prove the mutation never ran.'],
    [example('Inspect worker state', {}, session), example('Recover an operation outcome', { operationId: 'OPERATION-ID' }, session)], ['session.cancel', 'session.reconnect', 'session.close']),
  'session.close': doc('Cancel active work, release owned runtime connections and shut down the worker.', 'Use when exploration or the TDD loop is finished.',
    { closed: 'true once host cleanup has completed.' },
    ['Requires --session. keepAppAlive retains a managed app when requested; otherwise owned app resources are stopped.', 'Operation records remain local evidence. Closing a session does not delete canonical test run artifacts.'],
    [example('Close the worker and owned app', {}, session), example('Close while retaining the app', { keepAppAlive: true }, session)], ['session.status', 'session.open']),
  'session.reconnect': doc('Refresh the host’s app connection after queued work settles.', 'Use after a transport disconnect when the same worker and app should be retained.',
    { 'connected / endpoint / tdd / workflow / closed': 'Host status returned directly.' },
    ['Requires --session; waits for the host queue before reconnecting. Use tdd reconnect for the persistent runtime’s own driver.', 'Does not retry a previous command or restart a dead app. Version mismatch requires closing/reopening the worker.'],
    [example('Refresh the host transport', {}, session)], ['session.status', 'tdd.reconnect', 'app.snapshot']),
  'session.cancel': doc('Request cancellation of one active or queued session operation.', 'Use to stop long work while retaining the worker for outcome inspection.',
    { operationId: 'Requested operation identity.', cancellationRequested: 'Whether that operation was still active when the request arrived.' },
    ['Requires --session and operationId. Cancellation acknowledgement is not completion; poll session status for its final journal state.', 'Cancellation waits for owned work to settle before later mutations execute. false may mean the operation already completed; inspect its status.'],
    [example('Cancel a known operation', { operationId: 'OPERATION-ID' }, session)], ['session.status', 'session.close']),
